scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_293'] || []

control 'CKV_AWS_293' do
  title 'Ensure that AWS database instances have deletion protection enabled'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_db_instance resources that actually exist, read through the
    stock inspec-aws aws_rds_instance resource.
  DESC

  desc 'rationale', <<~RATIONALE
    Deletion protection is the difference between a mistyped identifier
    costing an argument and costing the database.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_db_instance: deletion_protection is True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_db_instance:

      resource "aws_db_instance" "example" {
        deletion_protection = true
      }

    Out of band — aws_db_instance:

      aws rds modify-db-instance --db-instance-identifier <id> --deletion-protection --apply-immediately
  FIX

  tag checkov_id:            'CKV_AWS_293'
  tag checkov_category:      'GENERAL_SECURITY'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_db_instance]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/db_instance#deletion-protection'
  tag nist:                  ['CP-9', 'SI-12']
  tag nist_r4:               ['CP-9', 'SI-12']
  tag cci:                   ['CCI-000535', 'CCI-001678']
  tag ksi:                   ['KSI-RPL-ABO']
  tag severity:              'low'
  tag severity_source:       'assessed'
  tag nist_source:           'reviewed'
  tag implementation_status: 'implemented'

  # Enumerated at control scope, then each asset asserted on its own. The
  # resource is an ARGUMENT to `describe`, which evaluates on the control --
  # calling it inside the block would defer it into the example.
  #
  # Every call carries aws_region: a stock resource otherwise reads only the
  # region the connection was built with, and every other region's resources
  # report as absent, which renders Not Applicable rather than unexamined.
  found = checkov_scan_regions(scan_regions).flat_map do |region|
    aws_rds_instances(aws_region: region).db_instance_identifiers.to_a.map { |id| [id, region] }
  end

  # A plural resource whose table is built from the API response returns nil for
  # a column that does not exist, rather than raising. Passing that on gives
  # "`[:x]` must be provided" and kills the control. Blank ids are separated out
  # and asserted on below, so a wrong `ids` column is a visible failure rather
  # than a crash or a silent Not Applicable.
  unusable = found.count { |id, _r| "#{id}".strip.empty? }
  found = found.reject { |id, _r| "#{id}".strip.empty? }
  in_scope = found.reject { |id, _r| checkov_exempt?(id: id, type: 'aws_db_instance', rules: exempt) }

  if unusable.positive?
    describe "aws_db_instance enumeration" do
      it 'produced usable identifiers' do
        expect(unusable).to eq(0),
          "#{unusable} row(s) had a blank id — the `ids` column in resource_map.yml "          'likely names a field this resource does not expose'
      end
    end
  end

  # `unusable.positive?` keeps the control APPLICABLE when every id came back
  # blank. Without it only_if skips the control, and the wrong-column case this
  # guard exists to catch is exactly the case it would suppress — a Not
  # Applicable that means "the enumeration is broken".
  applicable = !in_scope.empty? || unusable.positive?
  impact 0.3
  impact 0.0 unless applicable
  only_if('no aws_db_instance in scope') { applicable }

  in_scope.each do |id, region|
    describe aws_rds_instance(db_instance_identifier: id, aws_region: region) do
      its('deletion_protection') { should eq true }
    end
  end
end
